#!/usr/bin/env python3
"""Incremental bounded log-only workload census. Missing coverage is never zero."""
import argparse,re
from campaign_common import ROOT,REPO,PROJECTS,read,save,sha,utc,all_ended
from importlib.util import spec_from_file_location,module_from_spec

COUNTERS=re.compile(r'(?<![A-Za-z0-9_])([A-Za-z][A-Za-z0-9_]*)=(-?[0-9]+)(?=[ ,}\]]|$)')
RANKS={
 'loop':['observations','scalars','trials','budgetsSkipped','rawFallbacks'],
 'pubsub':['localCandidatePairs','localPublicationCandidatePairs','localNativeMatches','localNdCombinations','localDataCallbacks'],
 'saved':['savedOutputPositions','savedSelectedRecords','savedReversedViews','savedReplayDirectMatches'],
 'routes':['prePublicationLocalOffers','prePublicationDeadLocals','preparedExitEntries','preparedExitTargetMasks','completionDuplicates'],
}
DEFINITIONS={
 'c5PlanOccurrences':'K: checked row/member occurrences included in successfully built prepared plans; failed factory prefixes are not necessarily included.',
 'c5AcceptedOccurrences':'k: accepted entry tickets in successfully built plans; accepted entry-only/no-output occurrences may not produce programs.',
 'c5OutputPrograms':'s: distinct exact output programs across successfully built plans; not unique across different plan contexts.',
 'c5ProgramQueries':'Prepared plan intersections, including empty-base answers and queries that later overflow and fall back.',
 'c5PacketStreams':'Native protected/ordinary stream traversals in the prepared path, not unique packets.',
 'c5ScalarEnumerations':'Scalar mark/path memberships visited in prepared stream traversals; may include work discarded on overflow.',
 'c5ProgramCandidates':'Scalar/program candidate pairs visited after output index selection.',
 'c5SelectedReferences':'Distinct per-program/per-stream selected Conclusions inserted into query-local buckets.',
 'c5SelectedReferencePeak':'Maximum selected references in one query, not an additive total; may include the overflow-triggering reference.',
 'c5BucketFallbacks':'Prepared queries whose selected-reference bound is exceeded; native full query recomputes after partial pure work is discarded.',
 'c5StreamPacks':'Whole-program protected/ordinary stream packing operations, not per-leaf cuts.',
 'c5RowAttempts':'CHANGED: prepared output-program finalizations plus native/fallback row-packet attempts. Do not compare directly with old all-row call counts.',
 'c5PlanFallback*':'Factory fallback reason counts, not total native executions through cached negative plans.',
 'prePublicationLocalOffers':'Actual LocalVar raw-summary gate invocations; distinct from prepared cache entries and later local-boundary tests.',
 'prePublicationDeadLocals':'Raw-summary gate invocations returning DeadData; repeated invocations are not unique dropped facts.',
 'preparedExitEntries':'Prepared route cache entries, not raw-summary invocations.',
 'preparedExitTargetMasks':'Built local target masks; dynamic ActualStarts is still intersected at use.',
 'localPublicationLinearPairs':'Arithmetic row/input/member all-pairs bound, not proof every prior version executed every native predicate.',
 'savedOutputPositions':'Positional saved-reader selections; positions sharing a record still retain their ordinals.',
}

def ratio(n,d):return n/d if d else None
def parse(message,project):
    marker=re.match(r'^(BIDI_[A-Z0-9_]+) run=([1-9][0-9]*)\b',message)
    if not marker:return
    tag,number=marker[1],marker[2];run=project.setdefault('runs',{}).setdefault(number,{'methods':{},'markers':{},'sampleCoverage':{}})
    if tag in {'BIDI_RUN_START','BIDI_RUN_END','BIDI_BARRIER_END','BIDI_JOINED_RELEASE','BIDI_STATIC_WRITER_BIND','BIDI_ANALYSIS_END'}:run['markers'][tag]=message
    if tag=='BIDI_RUN_START':run['direction']=re.search(r'\bdirection=(\w+)',message)[1];run['fieldLimit']=int(re.search(r'\blimit=([0-9]+)',message)[1])
    if tag=='BIDI_STATIC_CLOSURE_LOOKUP':run['globalDemandStore']={'counters':{k:int(v)for k,v in COUNTERS.findall(message)},'rawLog':message,'scope':'All callers of this printed DemandStore; native/prepared/observer/public summary work can overlap.'}
    elif tag=='BIDI_LOOP_BLOCK_STATISTICS':run['reportedLoopMethodCount']=dict((k,int(v))for k,v in COUNTERS.findall(message)).get('methods')
    elif tag in {'BIDI_LOOP_BLOCK_METHOD','BIDI_LOOP_BLOCK_ABORTED'}:
        if ' method='not in message or ' layoutBlocks='not in message:run['sampleCoverage']['unparsedMethodLines']=run['sampleCoverage'].get('unparsedMethodLines',0)+1;return
        method,_,tail=message.partition(' method=')[2].partition(' layoutBlocks=')
        counters={k:int(v)for k,v in COUNTERS.findall('layoutBlocks='+tail)}
        run['methods'][method]={'method':method,'counters':counters,'logTag':tag,'rawLog':message}
    elif tag in {'BIDI_BODY_WORK_STATISTICS','BIDI_IDENTITY_STORAGE_STATISTICS'}:
        run[tag]={'counters':{k:int(v)for k,v in COUNTERS.findall(message)},'rawLog':message}
    elif tag in {'BIDI_C5_ROW_SAMPLE','BIDI_BODY_WORK_METHOD','BIDI_BODY_WORK_ABORTED_METHOD'}:
        samples=run.setdefault('boundedTextSamples',{}).setdefault(tag,[])
        samples.append({'text':message[:4096],'textComplete':len(message)<=4096,'notAnExactFullFactTrace':True})
        if len(samples)>64:samples.pop(0);run['sampleCoverage']['readerSamplesDropped']=run['sampleCoverage'].get('readerSamplesDropped',0)+1

def derive(run):
    methods=run['methods'];coverage={'loggedMethodCount':len(methods),'reportedLoopMethodCount':run.get('reportedLoopMethodCount'),'methodSelection':'Completed run emits top24 loop methods by steps; aborted run emits a different bounded joined-owner sample. These are not global all-work totals.','loggedFractionOfReportedLoopMethods':ratio(len(methods),run.get('reportedLoopMethodCount'))}
    ranked={}
    for family,keys in RANKS.items():
        ranked[family]={}
        for key in keys:
            available=[row for row in methods.values()if key in row['counters']]
            if not available:continue
            denominator=sum(row['counters'][key]for row in available)
            ranked[family][key]={'denominator':denominator,'denominatorScope':'SUM_OF_LOGGED_METHOD_COUNTER_ONLY_NOT_GLOBAL','rows':[{'method':row['method'],'count':row['counters'][key],'shareOfLoggedCounter':ratio(row['counters'][key],denominator)}for row in sorted(available,key=lambda row:row['counters'][key],reverse=True)[:12]]}
    globalc=run.get('globalDemandStore',{}).get('counters',{})
    run['derived']={'coverage':coverage,'rankedLoggedMethods':ranked,'prepared':{'K':globalc.get('c5PlanOccurrences'),'k':globalc.get('c5AcceptedOccurrences'),'s':globalc.get('c5OutputPrograms'),'programsPerAcceptedOccurrence':ratio(globalc.get('c5OutputPrograms'),globalc.get('c5AcceptedOccurrences'))if 'c5OutputPrograms'in globalc and'c5AcceptedOccurrences'in globalc else None,'pureDuplicateProgramRatio':'NOT_DERIVED: accepted no-output occurrences and failed factory prefixes need separate counts.','packetStreams':globalc.get('c5PacketStreams'),'scalarEnumerations':globalc.get('c5ScalarEnumerations'),'programCandidates':globalc.get('c5ProgramCandidates'),'selectedReferences':globalc.get('c5SelectedReferences'),'selectedReferencePeak':globalc.get('c5SelectedReferencePeak'),'bucketFallbacks':globalc.get('c5BucketFallbacks'),'factoryFallbacks':{key:value for key,value in globalc.items()if key.startswith('c5PlanFallback')},'legacyRowAttemptMeaningChanged':True}}

def main():
    parser=argparse.ArgumentParser();parser.add_argument('--max-bytes-per-project',type=int,default=32*1024*1024);parser.add_argument('--seal-input-hashes',action='store_true');args=parser.parse_args();assert args.max_bytes_per_project>0
    if args.seal_input_hashes:all_ended()
    spec=spec_from_file_location('bounded_live',ROOT/'analysis-tools/live-controls.py');bounded=module_from_spec(spec);spec.loader.exec_module(bounded)
    state=read(ROOT/'preparation/workload-reader-state.json',{'projects':{}});out=read(ROOT/'analysis/workload-log-census.json',{'projects':{}})
    for name in PROJECTS:
        directory=ROOT/'projects'/name/'bidi';log=directory/'analyzer.log'
        if not log.is_file():continue
        row=out['projects'].setdefault(name,{'runs':{}});cursor=state['projects'].setdefault(name,{})
        for message in bounded.consume(log,cursor,args.max_bytes_per_project):parse(message,row)
        for run in row['runs'].values():derive(run)
        row['logCoverage']={key:cursor.get(key,0)for key in ['offset','unreadBytes','oversizedLinesDiscarded']};row['summary']=read(directory/'summary.json');row['manifest']=read(directory/'manifest.json',{})
        stat=log.stat();row['input']={'log':str(log),'bytesAtRead':stat.st_size,'mtimeNsAtRead':stat.st_mtime_ns,'fullLogSha256':None,'hashState':'LIVE_OR_PARTIAL_NOT_FULLY_HASHED','manifestSha256':sha(directory/'manifest.json')if(directory/'manifest.json').exists()else None,'summarySha256':sha(directory/'summary.json')if(directory/'summary.json').exists()else None}
        if args.seal_input_hashes:
            assert cursor.get('unreadBytes',0)==0,'Repeat bounded reads to EOF before sealing input hashes'
            row['input'].update(fullLogSha256=sha(log),hashState='FINISHED_INPUT_HASHED_AFTER_ALL_ENDED')
    out.update(schema='opentaint.loop-demand-trie.workload-log.v1',state='CURRENT_LOG_CENSUS'if out['projects']else'NO_CURRENT_LOGS_PREPARATION_ONLY',utc=utc(),measuredRevision=read(ROOT/'preparation/launch-manifest.json',{}).get('revision'),counterDefinitions=DEFINITIONS,readerSha256=sha(__file__),limits=['This is log/counter evidence, not CPU or a complete fact trace.','Absent counter lines and unlogged methods are unknown, not zero.','End-state gauges, cumulative query counts, scalar memberships and sampled widths have different denominators.','Prepared c5RowAttempts now includes program finalizations; compare the explicit new K/k/s/stream counters instead of old row-call totals.','No unique annotated key count is inferred from event totals or bounded firstBranch samples.'])
    save(ROOT/'preparation/workload-reader-state.json',state);save(ROOT/'analysis/workload-log-census.json',out)
    print({name:list(row['runs'])for name,row in out['projects'].items()})

if __name__=='__main__':main()

