package org.opentaint.dataflow.bidi.diagnostics

import org.opentaint.dataflow.ap.ifds.AccessPathBase
import org.opentaint.dataflow.bidi.ap.*
import org.opentaint.dataflow.bidi.driver.*
import org.opentaint.dataflow.bidi.engine.*
import org.opentaint.dataflow.bidi.fixtures.*
import org.opentaint.dataflow.bidi.interp.*
import org.opentaint.dataflow.bidi.interp.CallPoint.*
import org.opentaint.dataflow.bidi.interp.StageKind.*
import org.opentaint.dataflow.bidi.store.*
import kotlin.time.Duration.Companion.seconds

/** Small native discovery probe, not a claim of actual JIR/source/rule equivalence.
 * Roots and all MicroEdgeBuilder statements are immutable before forms are read.
 * Only production policies run. Counterfactual native matching is queried after
 * each completed run, with no result fed back into execution.
 */
object ConductorWorkflowExpressionProbe {
    private val arg = AccessPathBase.Argument(0)
    private val ret = AccessPathBase.Return
    private val v0 = AccessPathBase.LocalVar(0)
    private val v1 = AccessPathBase.LocalVar(1)
    private val v2 = AccessPathBase.LocalVar(2)
    private const val RULE = "java.security.graaljs-polyglot-code-injection"
    private const val PACKET_CAP = 512
    private const val MATCH_CAP = 2048
    private fun quote(value: String): String = "\"" + buildString {
        for (ch in value) append(when (ch) {
            '\\' -> "\\\\"; '"' -> "\\\""; '\n' -> "\\n"; '\r' -> "\\r"; '\t' -> "\\t"
            else -> if (ch.code < 32) "\\u%04x".format(ch.code) else ch.toString()
        })
    } + "\""
    private fun emit(kind: String, vararg fields: Pair<String, Any?>) {
        println((listOf("kind" to kind) + fields).joinToString(",", "{", "}") { (key,value) ->
            quote(key) + ":" + when (value) {
                null -> "null"; is Number, is Boolean -> value.toString(); else -> quote(value.toString())
            }
        })
    }
    private fun straight(size: Int) = List(size) { i -> if (i+1<size) listOf(i+1) else emptyList() }
    private fun pattern(f: DriverFixtures, value: Pattern): String {
        val fact=value.fact
        val mark=when(val token=fact.mark) {
            is MarkSlot.Concrete -> "CONCRETE(${token.mark.id},${f.manager.marks.key(token.mark)},${f.manager.marks.name(token.mark)})"
            is MarkSlot.Star -> "FLOW(mx=${token.excluded.ids.joinToString { id -> "$id:${f.manager.marks.key(TaintMark(id))}" }})"
        }
        return "${fact.base}.${fact.path.map(f.manager.accessors::accessor)}:${fact.tail}:$mark:E=${value.exclusion}"
    }
    private fun premise(f: DriverFixtures, value: PremiseKey) = value.members.mapIndexed { i,p -> "$i=${pattern(f,p.toPattern())}" }
    private fun facts(f: DriverFixtures, value: Facts): String {
        val leaves=f.ops.leaves(value).iterator();val all=ArrayList<String>()
        while(leaves.hasNext()) {
            if(all.size==PACKET_CAP) return "WHOLE_PACKET_DROP(expansionCap=$PACKET_CAP,atLeast=${PACKET_CAP+1})"
            all+=pattern(f,leaves.next())
        }
        val protected=(value as? TaintTree)?.protectedPart()?.let { part ->
            val rows=f.ops.leaves(part).take(PACKET_CAP+1).map { pattern(f,it) }.toList()
            if(rows.size>PACKET_CAP) return "WHOLE_PACKET_DROP(protectionExpansionCap=$PACKET_CAP)"
            rows
        }.orEmpty()
        return "layer=${value.layer}; ordinary=$all; protected=$protected; complete=true"
    }
    private fun call(f: DriverFixtures, key: MethodKey, source: AccessPathBase,
                     destination: AccessPathBase): CallPlan = CallPlan(setOf(source,destination), listOf(
        CallStage.Edges(BEFORE, AFTER, PASS_OVER, f.summary(keepEdge(source))),
        CallStage.Edges(BEFORE, BOUND, BIND_IN, f.summary(ZERO_KEEP,starEdge(source,emptyList(),arg,emptyList()))),
        CallStage.Actions(BOUND, ADDED, emptyList()),
        CallStage.Callees(ADDED, RETURNED, listOf(key)),
        CallStage.Actions(RETURNED, REWRITTEN, emptyList()),
        CallStage.Edges(REWRITTEN, AFTER, BIND_BACK, f.summary(ZERO_KEEP,starEdge(ret,emptyList(),destination,emptyList()))),
    ),emptyList(),BEFORE,AFTER)

    @JvmStatic fun main(args: Array<String>) = DriverFixtures().use { f ->
        val p=f.program
        val workflowDef=p.field("StartWorkflowRequest.workflowDef")
        val definition=p.field("StartWorkflowInput.workflowDefinition")
        val modelDefinition=p.field("WorkflowModel.workflowDefinition")
        val tasks=p.field("WorkflowDef.tasks")
        val element=p.field("Iterable.Element")
        val workflowTask=p.field("TaskMapperContext.workflowTask")
        val expression=p.field("WorkflowTask.expression")
        val mark=MarkSlot.Concrete(p.mark("T"))
        val ctor=p.method("StartWorkflowInput factory source-shape",straight(4),3).key()
        val model=p.method("createWorkflowModel source-shape",straight(5),4).key()
        val start=p.method("DeciderService.startWorkflow source-shape",straight(6),5).key()
        val builder=p.method("TaskMapperContext.Builder source-shape",straight(4),3).key()
        val mapper=p.method("SwitchTaskMapper.getMappedTasks source-shape",straight(6),5).key()
        val python=p.method("PythonEvaluator.evaluate shared-expression sink-shape",straight(2),1).key()
        val script=p.method("ScriptEvaluator.getSource shared-expression sink-shape",straight(2),1).key()
        val source=PathEdge(ZERO_FACT,PathFact(arg,emptyList(),Tail.ANY_TAINT,mark),ExclusionSet.Empty)
        // The model factory calls the decider after writing its definition field.
        p.statement(ctor,1,MicroEdgeBuilder().apply { read(v0,arg,listOf(workflowDef)) }.build())
        p.statement(ctor,2,MicroEdgeBuilder().apply { write(ret,listOf(definition),false,listOf(v0),emptyList()) }.build())
        p.statement(model,1,MicroEdgeBuilder().apply { read(v0,arg,listOf(definition)) }.build())
        p.statement(model,2,MicroEdgeBuilder().apply { write(v1,listOf(modelDefinition),false,listOf(v0),emptyList()) }.build())
        // Complete constructor -> model -> decider call sequence.
        val entry=p.method("WorkflowResource.testWorkflow complete source-shape",straight(5),4).key()
        val keys=listOf(entry,ctor,model,start,builder,mapper,python,script)
        p.entry(entry,RuleStatement(f.summary(ZERO_KEEP,source),StatementSummary.EMPTY,emptyList()))
        p.call(entry,1,call(f,ctor,arg,v0));p.call(entry,2,call(f,model,v0,v1));p.call(entry,3,call(f,start,v1,v2))
        // Return the allocated model after the setter. No weak base row is synthesized.
        p.statement(model,3,MicroEdgeBuilder().apply { move(ret,v1) }.build())
        // Read the same four logical source fields as the saved shortest witness.
        p.statement(start,1,MicroEdgeBuilder().apply { read(v0,arg,listOf(modelDefinition)) }.build())
        p.statement(start,2,MicroEdgeBuilder().apply { read(v1,v0,listOf(tasks)) }.build())
        p.statement(start,3,MicroEdgeBuilder().apply { read(v2,v1,listOf(element)) }.build())
        p.call(start,4,call(f,builder,v2,v0))
        p.statement(builder,1,MicroEdgeBuilder().apply { write(ret,listOf(workflowTask),false,listOf(arg),emptyList()) }.build())
        // builder is a factory with return value passed into the mapper by a helper.
        p.call(builder,2,call(f,mapper,ret,v0))
        p.statement(mapper,1,MicroEdgeBuilder().apply { read(v0,arg,listOf(workflowTask)) }.build())
        p.statement(mapper,2,MicroEdgeBuilder().apply { read(v1,v0,listOf(expression)) }.build())
        p.call(mapper,3,call(f,python,v1,v2));p.call(mapper,4,call(f,script,v1,v2))
        val sinks=listOf(python to "PythonEvaluator.evaluate",script to "ScriptEvaluator.getSource").map { (key,name) ->
            val sink=SinkRule(f.rule("$RULE:$name"),0,listOf(p.pattern(arg,mark=mark)),emptyList())
            p.exit(key,1,ExitRules(RuleStatement(StatementSummary.EMPTY,StatementSummary.EMPTY,listOf(sink)),false,emptySet()))
            sink.rule.id
        }
        emit("PROBE_SCOPE","shapeOnly" to true,"actualJirOrRuleEquivalence" to false,"productionPolicyOnly" to true,
            "sourceTail" to source.to.tail,"sinkIds" to sinks,"currentRevision" to "8331bf9e326ddd1bd5083dbc50456963d6b26b52")
        val driver=f.driver(FixedLimits(listOf(1,1,2,3,4,5,6,7)),budget=20.seconds,run1MarkMode=MarkMode.FULL)
        val report=driver.analyze(listOf(entry))
        for((ordinal,result) in f.results.withIndex()) {
            emit("RUN","run" to result.runIndex,"status" to result.status,"direction" to result.direction,"fieldLimit" to f.configs[ordinal].fieldLimit)
            for(actor in result.analyzers) for((i,value) in actor.summaries.all())
                emit("CURRENT_SUMMARY","run" to result.runIndex,"owner" to actor.key,"P" to premise(f,i),"F" to facts(f,value))
            var visited=0;var dropped=0
            for(key in keys) {
                val publications=result.analyzers.firstOrNull { it.key==key }?.summaries?.all()?.toList().orEmpty()
                for(link in f.links(result.runIndex,key)) for((i,value) in publications) {
                    if(i.size!=1) continue
                    if(visited++>=MATCH_CAP) { dropped++;continue }
                    val actual=f.manager.factsOf(link.addedFact.fact,link.addedFact.exclusion,link.linkLayer)
                    val member=i.member(0)
                    val native=f.ops.satisfying(actual,member,f.configs[ordinal].mode,false)
                    val selected=f.ops.matchSummary(actual,member,f.configs[ordinal].mode,false,SummaryMatchRole.CURRENT)
                    if(native!=null && selected==null) emit("NATIVE_ACCEPT_SELECTED_REJECT","run" to result.runIndex,
                        "owner" to key,"caller" to link.caller.caller,"callIndex" to link.caller.call.location.index,"scope" to link.caller.scope,
                        "callerP" to premise(f,link.caller.premise),"actual" to facts(f,actual),"I" to premise(f,i),"O" to facts(f,value),"nativeMatched" to facts(f,native),"counterfactualOnly" to true)
                }
            }
            emit("MATCH_AUDIT_COVERAGE","run" to result.runIndex,"attemptedPairs" to visited,"pairsDropped" to dropped,"cap" to MATCH_CAP)
        }
        for(frontier in driver.frontiers) emit("FRONTIER","run" to frontier.run,"direction" to frontier.direction,
            "outgoingPairs" to frontier.demandEdges.values.sum(),"reports" to frontier.reportedSinks,"targets" to frontier.targetDemand)
        val found=report.entries.map { it.descriptor.key.ruleId }.toSet()
        emit("FINAL","end" to report.end,"foundRuleIds" to found,"expectedSharedExpressionSinks" to sinks,"missingSharedExpressionSinks" to sinks.filter { it !in found },
            "fidelityGapIfPass" to "This fixture does not load actual JIR Spring rules, collection/getter models, aliases, source predicates or Python string loop.")
        check(report.end.status==RunStatus.COMPLETE) { "Probe did not complete: ${report.end}" }
        check(found.containsAll(sinks)) { "Shared expression sinks missing: ${sinks.filter { it !in found }}" }
    }
}

package org.opentaint.dataflow.bidi.diagnostics

import org.opentaint.dataflow.ap.ifds.AccessPathBase
import org.opentaint.dataflow.bidi.ap.*
import org.opentaint.dataflow.bidi.driver.*
import org.opentaint.dataflow.bidi.engine.*
import org.opentaint.dataflow.bidi.fixtures.DriverFixtures
