        val result=driver.analyze(listOf(root))
        val found=result.entries.any{it.descriptor.key.ruleId==sink.rule.id}
        emit("CASE","depth" to depth,"childFirst" to childFirst,"readBeforeWrite" to readBeforeWrite,
            "found" to found,"end" to result.end,"revision" to "8331bf9e326ddd1bd5083dbc50456963d6b26b52")
        for(frontier in driver.frontiers)emit("FRONTIER","depth" to depth,"childFirst" to childFirst,"readBeforeWrite" to readBeforeWrite,
            "run" to frontier.run,"direction" to frontier.direction,"demand" to frontier.demandEdges,"targets" to frontier.targetDemand,"reports" to frontier.reportedSinks)
        for(config in f.configs) {
            emit("SOURCE_PERMISSION","run" to config.index,"depth" to depth,"childFirst" to childFirst,"readBeforeWrite" to readBeforeWrite,
