            emit("SOURCE_HITS","run" to run.runIndex,"method" to actor.key,"hits" to actor.sourceHits?.occurrences()?.toList())
            for((initial,value)in actor.summaries.all())emit("SUMMARY","run" to run.runIndex,"method" to actor.key,"row" to image(f,initial,value))
            for(row in f.processed.filter{it.run==run.runIndex&&it.method==actor.key&&it.delta.node.location.index in setOf(read,rootArm,childWrite,childMove,callAt,sinkRead)})
                emit("POINT","run" to row.run,"method" to row.method,"point" to row.delta.node.location.index,"row" to image(f,row.delta.premise,row.delta.facts))
        }
        check(result.end.status==RunStatus.COMPLETE){"Noncomplete discovery case: ${result.end}"}
        found
    }

    @JvmStatic fun main(args:Array<String>) {
        val cases=ArrayList<Triple<Int,Boolean,Boolean>>()
        val depths=if(args.isEmpty())listOf(1,3,5)else args.map(String::toInt)
        for(depth in depths)for(childFirst in listOf(false,true))for(read in listOf(false,true))cases+=Triple(depth,childFirst,read)
